    try {
      const stat = fs.statSync(source);
      return kind === "directory" ? stat.isDirectory() : stat.isFile();
    } catch { return false; }
  });
  const optional = (source, resolve = true) => source === undefined ? null : resolve ? fs.realpathSync(source) : source;
